Something like this:

```jsx
function usePokemon(name) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!name) return;
    let ignore = false;
    setLoading(true);
    setError(null);

    fetch(`https://pokeapi.co/api/v2/pokemon/${name.toLowerCase()}`)
      .then(res => {
        if (!res.ok) throw new Error('Not found');
        return res.json();
      })
      .then(json => { if (!ignore) setData(json); })
      .catch(err => { if (!ignore) setError(err.message); })
      .finally(() => { if (!ignore) setLoading(false); });

    return () => { ignore = true; };
  }, [name]);

  return { data, loading, error };
}
```

The `ignore` flag is the part that keeps it clean: if `name` changes before the first request finishes, the old response gets thrown away instead of overwriting the new one.
